"""Private Chemistry review, normalized records 121–160. No shared bank writes."""
import copy,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]; OUT=Path(__file__).parent
qs=[q for q in json.loads((ROOT/'ops/jamb/source-pool.json').read_text(encoding='utf8'))['questions'] if q['subject']=='chemistry'][120:160]
RX='https://openstax.org/books/chemistry-2e/pages/4-2-classifying-chemical-reactions'
GAS='https://openstax.org/books/chemistry-2e/pages/9-4-effusion-and-diffusion-of-gases'
EL='https://openstax.org/books/chemistry/pages/17-7-electrolysis'
REB='https://elearning.reb.rw/pluginfile.php/11670/mod_resource/content/1/S3%20Chemistry%20SB.pdf'
rows=[]
def page(q):
 if q['year']==1987:return 17
 if q['year']==1985 or q['num']==3:return 13
 return 14 if q['num']<=17 else 15
def yes(i,a,e,urls,*,question=None,options=None,year=None,audit='',check=None):
 q=qs[i-121];u=copy.deepcopy(q)
 if year:u['year']=year
 if question:u['question']=question
 if options:u['options']=dict(zip('ABCDE',options))
 u['answer']=a;u['ai_explanation']=e;u['format']=len(u['options'])
 rows.append({'id':q['id'],'before':q,'update':u,'source_pdf_page':page(u),'actual_source_year':u['year'],'actual_source_number':u['num'],'publication_candidate':True,'review_method':'ai-calculation-checked' if check else 'ai-source-checked','independent_reasoning':e,'source_urls':urls,'source_checked_at':'2026-09-12','private_repair_history':audit or 'Compared complete question and options against the supplied PDF; independently solved and wrote a teaching explanation.','calculation_check':check})
def no(i,why,*,year=None,answer=None):
 q=qs[i-121];temp={**q,'year':year or q['year']}
 rows.append({'id':q['id'],'before':q,'update':None,'source_pdf_page':page(temp),'actual_source_year':temp['year'],'actual_source_number':temp['num'],'publication_candidate':False,'hold_reason':why,'independently_indicated_answer':answer,'source_checked_at':'2026-09-12'})

yes(121,'C','Acid decomposes thiosulfate into sulfur and sulfur dioxide: S₂O₃²⁻ + 2H⁺ → S + SO₂ + H₂O. Sulfur forms the yellow precipitate. Sulfur dioxide is a reducing agent and turns acidified dichromate from orange to green. Thus the salt is sodium thiosulfate pentahydrate.',['https://edu.rsc.org/download?ac=522804',RX],question='Adding dilute hydrochloric acid to an aqueous solution of a crystalline salt gives a yellow precipitate and a gas that turns acidified dichromate paper green. Which salt is most likely?',options=['Na₂SO₄','Na₂S','Na₂S₂O₃·5H₂O','Na₂CO₃','NaHCO₃'],audit='Restored charge-balanced sodium formulae in C and D. Old explanation had another incorrect thiosulfate formula. Checked sulfur precipitate and SO₂ redox behaviour.',check='thiosulfate-balance')
yes(122,'A','Hydrogenation adds hydrogen across carbon–carbon double bonds in unsaturated oil molecules. Increasing saturation can turn the liquid oil into a firmer fat suitable for margarine.',['https://openstax.org/books/organic-chemistry/pages/8-6-reduction-of-alkenes-hydrogenation'],question='The process that hardens an unsaturated oil by adding hydrogen, as in margarine manufacture, is called',audit='Clarified the reaction being tested without claiming all modern margarine manufacturing uses this process.')
no(123,'Pb²⁺ (E), not the old Al³⁺ key, fits amphoteric hydroxide, insolubility in excess NH₃, and white PbCl₂. However option C is printed N++ in the PDF and its missing metal symbol cannot be inferred uniquely. Restore the complete distractor from a corroborated source.',answer='E')
yes(124,'D','Sodium chloride reduces the solubility of the soap in the aqueous mixture, causing the soap to separate. Glycerol remains in the liquid. This separation is called salting out.',['https://edu.rsc.org/exhibition-chemistry/soap-from-bacon-the-dangers-of-alkaline-solutions/2020068.article'],question='Which option most precisely describes the direct role of sodium chloride added during soap preparation?',options=['It reacts with glycerol','It purifies the soap','It accelerates decomposition of the fat and oil','It separates the soap from the glycerol-containing solution','It converts the fatty acid to its sodium salt'],audit='Corrected from/form and fat/fatty wording; made most-precise/direct qualifier explicit because B is broad while D identifies the actual separation mechanism.')
yes(125,'C','Sulfur forms cross-links between rubber polymer chains. These links limit how freely the chains slide past one another, making the rubber stronger and helping it recover its shape after stretching.',['https://openstax.org/books/organic-chemistry/pages/14-6-diene-polymers-natural-and-synthetic-rubbers'],question='What is the function of sulfur during the vulcanisation of rubber?',options=['To catalyse polymerisation of rubber molecules','To convert rubber from a thermosetting to a thermoplastic polymer','To form links that bind rubber chains together','To break down rubber polymer molecules','To shorten the rubber polymer chains'],audit='Removed next-year heading from E and restored C from/from-form typo. Avoided claiming every sulfur bridge is a disulfide.')
yes(126,'B','Seawater contains water together with dissolved salts and other substances. Its components are not combined in one fixed chemical ratio, so it is a mixture. Sugar and sodium chloride are compounds; iron is an element.',['https://openstax.org/books/chemistry-2e/pages/1-2-phases-and-classification-of-matter'],year=1987,options=['Granulated sugar','Seawater','Sodium chloride','Iron filings'],audit='Page 17 heading confirms 1987, not normalized 1986. Corrected filings spelling and preserved stable ID.')
yes(127,'B','At the same temperature and pressure, gas volumes are proportional to mole amounts. The ratio 10:5:10 simplifies to 2:1:2. Equation B has those coefficients and conserves two H atoms, two N atoms and four F atoms on each side.',[RX],question='At the same temperature and pressure, 10 cm³ of hydrogen fluoride reacts with 5 cm³ of dinitrogen difluoride (N₂F₂) to form 10 cm³ of a single gaseous product. Which equation fits these observations?',options=['HF + N₂F₂ → N₂HF₃','2HF + N₂F₂ → 2NHF₂','2HF + N₂F₂ → N₂H₂F₄','HF + 2N₂F₂ → N₄HF₄'],audit='Restored arrows, subscripts and same-temperature/pressure gas-volume premise. Retained the unbalanced D as an incorrect proposed equation; removed page marker.',check='gas-reaction-ratio')
no(128,'Independent stoichiometry gives 0.1 mol CO₂ = 6.02×10²² molecules (C): 10 g CaCO₃ and 0.2 mol HCl are exactly stoichiometric. PDF options B and D both print 6.02×10²³. Correct-answer calculation is settled, but restore the duplicate distractor before publishing the complete item.',year=1987,answer='C')
yes(129,'A','The molar mass of NaCl is 23 + 35.5 = 58.5 g mol⁻¹. Therefore 5.85 g contains 0.100 mol NaCl. Each formula unit contains one chlorine atom, so the number of chlorine atoms is 0.100 × 6.02 × 10²³ = 6.02 × 10²².',[RX],question='How many chlorine atoms are present in 5.85 g of NaCl? [Na = 23, Cl = 35.5; Avogadro constant = 6.02 × 10²³ mol⁻¹]',options=['6.02 × 10²²','5.85 × 10²³','6.02 × 10²³','5.85 × 10²⁴'],check='chlorine-atoms')
no(130,'The actual 1987 source asks for mass of solid acetylene gas without giving a reactant amount or gas volume. No quantitative answer follows from CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂ alone. Recover the missing premise rather than reuse the guessed old 2.9 g answer.',year=1987)
yes(131,'B','Mg + 2HCl → MgCl₂ + H₂. The acid amount is 0.250 × 0.5 = 0.125 mol. Half as many moles of magnesium are needed: 0.0625 mol. Its mass is 0.0625 × 24 = 1.5 g.',[RX],question='What mass of magnesium reacts completely with 250 cm³ of 0.5 mol dm⁻³ HCl? [Mg = 24]',options=['0.3 g','1.5 g','2.4 g','3.0 g'],audit='Changed old D (3.0 g) to B (1.5 g); restored the 1:2 metal-to-acid mole ratio and moved atomic mass into the stem.',check='magnesium-mass')
yes(132,'C','For an ideal gas at constant volume and temperature, P = nRT/V, so pressure is proportional to the amount of gas. Halving the amount halves the pressure: 0.825/2 = 0.4125 atm, which rounds to 0.413 atm.',['https://openstax.org/books/chemistry-2e/pages/9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law'],year=1987,question='Oxygen occupies a fixed 2.76 litre container at 0.825 atm and 300 K. Half the amount of gas is removed while the temperature remains 300 K. What pressure does the remaining gas exert?',audit='Corrected quality to quantity/amount, made constant temperature explicit, and restored actual 1987 source year.',check='half-pressure')
no(133,'Graham calculation gives methane rate (200/50)√(32/16) cm³/s and time 80/(4√2)=14.142 s, so C is correct; old explanation was wrong. Both PDF options A and B are 20 seconds. Recover the duplicate distractor before complete-item publication.',answer='C')
yes(134,'D','At equal temperature and pressure, vapour density is proportional to molar mass. Ethanal, C₂H₄O, has molar mass 44; ethanoic acid and propanol each have 60, and dichloromethane has 85. Ethanal therefore has the lowest vapour density.',[GAS],year=1987,question='Which substance has the lowest vapour density when compared under the same conditions? [C = 12, H = 1, O = 16, Cl = 35.5]',options=['Ethanoic acid','Propanol','Dichloromethane','Ethanal'],audit='Restored dichloromethane spelling, constants and actual source year 1987.',check='vapour-masses')
no(135,'The source is actual 1987 page 17. Visual inspection shows both A and C as r=k/√d, with B=kd and D=k√d. Correct Graham dependence is known, but two correct options prevent a unique key; recover original alternatives, not just missing text formatting.',year=1987,answer='A and C duplicate correct dependence')
yes(136,'B','Atomic number 12 identifies magnesium. Its electron arrangement is 2,8,2, and it commonly loses two outer electrons to form Mg²⁺. It therefore forms ionic (electrovalent) compounds with valency 2.',['https://openstax.org/books/chemistry-atoms-first-2e/pages/3-4-electronic-structure-of-atoms-electron-configurations'],question='An element of atomic number 12 commonly forms compounds in which its bonding and valency are',options=['Electrovalent, with valency 1','Electrovalent, with valency 2','Covalent, with valency 2','Covalent, with valency 4'])
no(137,'Across a period, ionisation energy and electronegativity generally increase, radius decreases, and electron-affinity trends have exceptions. The intended general combination 1,3,4 is absent. Old C incorrectly excludes ionisation energy; recover options or original qualifier.')
yes(138,'D','The dissolved sugar amount is 34.2/342.0 = 0.100 mol. The original solution volume is 50/1000 = 0.050 dm³. Its saturated concentration is therefore 0.100/0.050 = 2.0 mol dm⁻³.',[RX],question='Evaporating 50 cm³ of a saturated sugar solution at 40 °C gives 34.2 g of dry sugar. The sugar molar mass is 342.0 g mol⁻¹. What is the saturated concentration at 40 °C?',options=['10.0 mol dm⁻³','7.0 mol dm⁻³','3.5 mol dm⁻³','2.0 mol dm⁻³'],check='sugar-solubility')
no(139,'PDF page 14 merges an incomplete solubility-curve question with unrelated salt/pH options. Both graphs need accessible accurate recovery and the original stem/options need disentangling. The imported Na₂CO₃ key does not answer the shown solubility question.')
yes(140,'A','An acid salt retains replaceable hydrogen from partial neutralisation of a polyprotic acid. NaHSO₄ retains one acidic hydrogen from H₂SO₄. The other listed salts do not retain such a hydrogen. Acidity of a salt solution alone is a different concept.',[RX],question='Which compound is an acid salt?',options=['NaHSO₄','Na₂SO₄','CH₃CO₂Na','Na₂S'])
yes(141,'D','Sugar dissolves mainly as neutral molecules and contributes essentially no mobile ions. Sodium hydroxide is a strong electrolyte, while hexanoic acid supplies some ions through partial ionisation. The sugar solution therefore conducts the least electricity.',['https://openstax.org/books/chemistry-2e/pages/11-2-electrolytes'],question='Which aqueous solution has the lowest electrical conductivity?',options=['2.00 mol dm⁻³ NaOH','0.01 mol dm⁻³ NaOH','0.01 mol dm⁻³ hexanoic acid','0.01 mol dm⁻³ sugar'],audit='Restored hexanoic acid spelling and consistent concentration units; independently identified non-electrolyte.')
no(142,'Anions SO₄²⁻ and OH⁻ migrate to the positive anode (A). The supplied page 14 cell diagram is absent from the record and B/C/D ion formulae are incomplete. Need an accessible diagram or lossless agreed text representation and complete alternative transcription before intake.',answer='A')
yes(143,'D','Charge equals current multiplied by time: Q = It. One hour is 3600 seconds, so Q = 6.5 × 3600 = 23400 C = 2.34 × 10⁴ C.',[EL],question='What charge passes through a solution when a current of 6.5 A flows for 1.0 hour?',options=['3.90 × 10² C','5.50 × 10³ C','6.54 × 10³ C','2.34 × 10⁴ C'],audit='Corrected old C key to D using seconds, not a fabricated charge result.',check='charge')
yes(144,'D','In Zn + 2HCl → ZnCl₂ + H₂, zinc changes oxidation state from 0 to +2 and hydrogen from +1 to 0. Electrons are transferred, making this a redox reaction. The other reactions do not change the elements’ oxidation states.',[RX],question='Which equation represents a redox reaction?',options=['AgNO₃ + NaCl → AgCl + NaNO₃','H₂S + Pb(NO₃)₂ → PbS + 2HNO₃','CaCO₃ → CaO + CO₂','Zn + 2HCl → ZnCl₂ + H₂'],audit='Restored NaNO₃ from NNO₃ by atom conservation and all arrows/subscripts; removed page marker. Checked all four atom balances and oxidation states.',check='redox-equations')
yes(145,'A','The base amount is 0.020 × 0.1 = 0.0020 mol. Since 102 J is released, the reaction enthalpy is negative: ΔH = −102/0.0020 = −51000 J mol⁻¹ = −51.0 kJ mol⁻¹.',[RX],question='Neutralising 20 cm³ of 0.1 mol dm⁻³ aqueous NH₄OH with 20.05 cm³ of 0.1 mol dm⁻³ HCl releases 102 J of heat. What is the molar enthalpy of neutralisation of the base?',options=['−51.0 kJ mol⁻¹','+57.3 kJ mol⁻¹','+57.0 kJ mol⁻¹','+51.0 kJ mol⁻¹'],audit='Changed wrong positive D to negative A; heat liberated is exothermic, regardless of weak-base identity.',check='neutralization-enthalpy')
no(146,'Water phase in the supplied equilibrium is printed H₂O(i), while the old explanation assumes gas. If liquid, compression favours products; if gas, gaseous coefficients are equal. Resolve phase from a reliable original before assigning B or C. Also A and D overlap as left shift.')
yes(147,'C','Air is approximately one-fifth oxygen by volume. The air volume is therefore about 10 ÷ 0.20 = 50 cm³. This is an approximate composition calculation.',['https://openstax.org/books/astronomy/pages/8-3-earths-atmosphere'],question='Approximately what volume of air contains 10 cm³ of oxygen?',options=['20 cm³','25 cm³','50 cm³','100 cm³'],audit='Restored missing cubic unit and retained approximate qualifier rather than claiming oxygen is exactly 20 percent.',check='air-volume')
yes(148,'D','Heated magnesium reacts with steam to produce magnesium oxide and hydrogen: Mg + H₂O(g) → MgO + H₂. Reaction with liquid water instead leads to magnesium hydroxide, so steam matches the stated oxide product.',[REB,'https://periodic-table.rsc.org/element/12/magnesium'],question='Which condition gives the reaction Mg + H₂O → MgO + H₂?',options=['Excess magnesium ribbon','Excess cold water','Very hot liquid water','Steam'],audit='Recovered option C merged into B. Source labels steam E with no D; normalised four visible alternatives to A–D, so steam key is D. Product is source MgO, not Mg(OH)₂.',check='magnesium-steam')
yes(149,'C','Hot carbon reduces steam: C + H₂O(g) → CO + H₂. The resulting mixture of carbon monoxide and hydrogen is called water gas.',['https://openstax.org/books/chemistry/pages/18-5-occurrence-preparation-and-compounds-of-hydrogen'],question='Which main gaseous products form when steam is passed over red-hot carbon?',options=['Hydrogen, oxygen and carbon dioxide','Hydrogen and carbon dioxide','Hydrogen and carbon monoxide','Hydrogen and carbonic acid'],audit='Changed old B (CO₂) to C (CO) and restored oxide names. Main-products qualifier avoids implying no side equilibria.',check='water-gas')
no(150,'C fits efflorescent Na₂CO₃·10H₂O, deliquescent FeCl₃ and hygroscopic concentrated H₂SO₄. However PDF distractors contain H₂SO₂ and FeSO₂·7H₂O, with uncertain carbonate hydrate in B. Recover full chemical alternatives instead of inventing formula corrections.',answer='C')
no(151,'Soap volumes are 25−10=15 cm³ before boiling and 20−15=5 cm³ after. Permanent:temporary hardness is 5:(15−5)=1:2 before any lather blank correction, absent from options. Need corrected table/options or stated blank, not old guessed 1:4.',answer='1:2 from stated data')
no(152,'CO and SO₂ are plausible main products (B), but some sulfur can form SO₃ (C); source says bound to contain with no operating conditions or main/trace qualifier. Old explanation categorically excluding SO₃ is unsound. Recover original intended qualifier and avoid categorical exhaust composition claims.',answer='B intended main products')
yes(153,'A','Microorganisms use dissolved oxygen while breaking down oxygen-demanding organic waste. If oxygen is consumed faster than it is replaced, less remains for fish and other aquatic organisms.',['https://www.usgs.gov/publications/chapter-a7-section-70-five-day-biochemical-oxygen-demand'],question='Why can oxygen-demanding wastes pollute water?',options=['They deplete oxygen needed by aquatic organisms','They increase oxygen needed by aquatic organisms','They increase other gases needed by aquatic organisms','They deplete other gases needed by aquatic organisms'])
yes(154,'C','Both gases can be oxidised further: 2SO₂ + O₂ → 2SO₃ and 2NO + O₂ → 2NO₂. Sulfur rises from oxidation state +4 to +6 and nitrogen from +2 to +4. The other pairs contain water or carbon dioxide, which do not undergo this ordinary further oxidation.',[RX,REB],question='In which pair can both oxides react further with oxygen to form higher oxides?',options=['NO and H₂O','CO and CO₂','SO₂ and NO','CO₂ and H₂O'],check='higher-oxides')
yes(155,'A','Hydrogen sulfide contains hydrogen and sulfur and forms black lead sulfide with lead(II) ethanoate. Chlorine contains only chlorine and bleaches moist litmus. These observations match the first pair.',[REB],question='Gas X blackens moist lead(II) ethanoate paper, while gas Y bleaches moist litmus paper. Which listed elements are present in X and Y respectively?',options=['H and S; Cl','H and O; Cl','H and S; C and O','H and Cl; S and O'],audit='Restored clear separation of X and Y and grammatical wording. Unique listed pair, without claiming chlorine is the only possible bleaching gas in isolation.')
yes(156,'C','Copper(II) sulfide is extremely insoluble and remains precipitated in dilute non-oxidising acid. Sodium sulfide, zinc sulfide and iron(II) sulfide react with dilute HCl to release hydrogen sulfide. Thus CuS is the acid-insoluble sulfide in the list.',['https://mymission.lamission.edu/userdata/paziras/chem102/chap_16.pdf'],question='Which sulfide is insoluble in dilute hydrochloric acid?',options=['Na₂S','ZnS','CuS','FeS'])
yes(157,'C','Chlorine in water forms hydrochloric acid and hypochlorous acid. Sunlight promotes decomposition of hypochlorous acid, with overall reaction 2HOCl → 2HCl + O₂. The evolved gas is oxygen.',[REB],question='Chlorine water is exposed to sunlight. Which gas is evolved?',options=['HCl','HOCl','O₂','Cl₂O₂'],check='chlorine-water')
yes(158,'B','Aluminium ions strongly hydrolyse carbonate in water, producing aluminium hydroxide and carbon dioxide rather than a stable simple aluminium carbonate. Iron(II), zinc and lead(II) form ordinary solid carbonates.',['https://www.open.edu/openlearn/science-maths-technology/what-chemical-compounds-might-be-present-drinking-water/content-section-4.1.2/?printable=1'],question='Which metal does not form a stable simple carbonate under ordinary aqueous preparation conditions?',options=['Fe','Al','Zn','Pb'],audit='Corrected false Fe key to Al. Added ordinary aqueous context to avoid absolute claims about unusual complexes or high-pressure chemistry.')
no(159,'A NaHS is chemically indicated: it neutralises NaOH, releases H₂S with acid, and H₂S reduces concentrated H₂SO₄ to sulfur. The first source sentence is missing its verb/subject context and option C is malformed NaS. Recover the actual full stem and sulfide formula before intake; old Na₂SO₃ key is inconsistent.',answer='A')
yes(160,'B','Quicklime, CaO, removes water by forming Ca(OH)₂ without consuming the ammonia. Ammonia reacts with common alternative drying agents such as concentrated sulfuric acid and calcium chloride, so quicklime is used.',['https://edu.rsc.org/experiments/ammonia-fountain-demonstration/979.article'],question='Which substance is normally used to dry ammonia gas?',options=['Concentrated sulfuric acid','Quicklime','Anhydrous calcium chloride','Magnesium sulfate'],audit='Removed page marker and restored chemical spelling; RSC explicitly supports the drying-agent choice.')

